    "DoHPolicy"; // Require encryption = 3
                 // Allow encryption = 2
                 // Prohibit encryption = 1
"HKLM\\Software\\Policies\\Microsoft\\Windows NT\\DNSClient";
    "DohPolicySetting"; // Allow DoH = 0
                        // Block DoH = 1
"HKLM\\Software\\Policies\\Microsoft\\Windows NT\\DNSClient";
    "DotPolicySetting"; // Allow DoT = 0
                        // Block DoT = 1
```

