                                // Disabled = 0
"HKLM\\SOFTWARE\\Policies\\Microsoft\\Windows\\WDI\\{54077489-683b-4762-86c8-02cf87a33423}";
    "EnabledScenarioExecutionLevel"; // Troubleshooting Only = 1
                                     // Prompt for Resolution = 2
                                     // Silent = 3
```

