                                       // Medium (default) = 2
                                       // Lowest = 3
"HKLM\\Software\\Policies\\Microsoft\\Windows NT\\Terminal Services";
    "VGOptimization_CompressionRatio"; // Highest (best quality) = 1
                                       // Medium (default) = 2
                                       // Lowest = 3
```

