"HKLM\\SOFTWARE\\Policies\\Microsoft\\FVE";
    "EncryptionMethodWithXtsOs"; // AES-CBC 128-bit = 3
                                 // AES-CBC 256-bit = 4
                                 // XTS-AES 128-bit (default) = 6
                                 // XTS-AES 256-bit = 7
