    "IdentificationField"; // Type: REG_DWORD
                           // Enabled = 1
                           // Disabled = 0
"HKLM\\Software\\Policies\\Microsoft\\FVE";
    "IdentificationFieldString"; // Text input
"HKLM\\Software\\Policies\\Microsoft\\FVE";
    "SecondaryIdentificationField"; // Text input
```

