"HKLM\\Software\\Policies\\Microsoft\\W32time\\TimeProviders\\NtpClient";
    "Type"; // NoSync = NoSync
            // NTP = NTP
            // NT5DS = NT5DS
            // AllSync = AllSync
"HKLM\\Software\\Policies\\Microsoft\\W32time\\TimeProviders\\NtpClient";
