                  "UpdateNotificationLevel": {
                    "Type": "REG_DWORD",
                    "Data": 0
                  }
                }
              }
            },
            {
              "label": "1 \u2013 Disable all notifications, excluding restart warnings",
              "config": {
                "HKLM\\Software\\Policies\\Microsoft\\Windows\\WindowsUpdate": {
                  "UpdateNotificationLevel": {
                    "Type": "REG_DWORD",
                    "Data": 1
                  }
                }
              }
            },
            {
              "label": "2 \u2013 Disable all notifications, including restart warnings",
              "config": {
                "HKLM\\Software\\Policies\\Microsoft\\Windows\\WindowsUpdate": {
                  "UpdateNotificationLevel": {
                    "Type": "REG_DWORD",
                    "Data": 2
                  }
                }
              }
            }
          ]
        }
      },
